#include <vector>
#include <cmath>
#define main hecbench_original_main
#include "scatterThrust-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
template<class T>double study_case(int n,int repeat,std::vector<double>&values,std::vector<double>&expected){std::vector<T>input(n),out(n);std::vector<int64_t>index(n);for(int i=0;i<n;i++){input[i]=T(i);index[i]=n-1-i;expected.push_back(double(T(n-1-i)));}T*di,*dr;int64_t*dx;cudaMalloc(&di,n*sizeof(T));cudaMalloc(&dr,n*sizeof(T));cudaMalloc(&dx,n*8);cudaMemcpy(di,input.data(),n*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(dx,index.data(),n*8,cudaMemcpyHostToDevice);double time=0;for(int j=0;j<repeat;j++){cudaMemset(dr,0,n*sizeof(T));cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();thrust::device_ptr<T>a(di),o(dr);thrust::device_ptr<int64_t>x(dx);thrust::scatter(a,a+n,x,o);cudaDeviceSynchronize();time+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;}cudaMemcpy(out.data(),dr,n*sizeof(T),cudaMemcpyDeviceToHost);for(T v:out)values.push_back(double(v));cudaFree(di);cudaFree(dr);cudaFree(dx);return time;}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;std::vector<double>values,expected;study_case<int8_t>(n,1,values,expected);study_case<int16_t>(n,1,values,expected);study_case<int32_t>(n,1,values,expected);study_case<int64_t>(n,1,values,expected);study_case<float>(n,1,values,expected);study_case<double>(n,1,values,expected);for(int trial=1;trial<=5;trial++){values.clear();expected.clear();double time=0;time+=study_case<int8_t>(n,repeat,values,expected);time+=study_case<int16_t>(n,repeat,values,expected);time+=study_case<int32_t>(n,repeat,values,expected);time+=study_case<int64_t>(n,repeat,values,expected);time+=study_case<float>(n,repeat,values,expected);time+=study_case<double>(n,repeat,values,expected);emit(trial,time,values,expected,repeat);}return 0;}
